}

public Date nextDateTime(DateTimeFormat format, String timeZone) {
    int year = 0, month = 0, day = 0;
    int hour, minute, second, millisecond = 0;

    switch (format) {
        case HMS:
            hour = nextInt(0);
            minute = nextInt(0);
            second = nextInt(0);
            break;
        case SMH:
            second = nextInt(0);
            minute = nextInt(0);
            hour = nextInt(0);
            break;
        case HMS_YMD:
            hour = nextInt(0);
            minute = nextInt(0);
            second = nextInt(0);
            year = nextInt(0);
            month = nextInt(0);
            day = nextInt(0);
            break;
        case HMS_DMY:
            hour = nextInt(0);
            minute = nextInt(0);
            second = nextInt(0);
            day = nextInt(0);
            month = nextInt(0);
            year = nextInt(0);
            break;
        case SMH_YMD:
            second = nextInt(0);
            minute = nextInt(0);
            hour = nextInt(0);
            year = nextInt(0);
            month = nextInt(0);
            day = nextInt(0);
            break;
        case SMH_DMY:
            second = nextInt(0);
            minute = nextInt(0);
            hour = nextInt(0);
            day = nextInt(0);
            month = nextInt(0);
            year = nextInt(0);
            break;
        case DMY_HMS:
        case DMY_HMSS:
            day = nextInt(0);
            month = nextInt(0);
            year = nextInt(0);
            hour = nextInt(0);
            minute = nextInt(0);
            second = nextInt(0);
            break;
        case YMD_HMS:
        case YMD_HMSS:
        default:
            year = nextInt(0);
            month = nextInt(0);
            day = nextInt(0);
            hour = nextInt(0);
            minute = nextInt(0);
            second = nextInt(0);
            break;
    }

    if (format == DateTimeFormat.YMD_HMSS || format == DateTimeFormat.DMY_HMSS) {
        millisecond = nextInt(0); // (ddd)
    }

    if (year >= 0 && year < 100) {
        year += 2000;
    }

    DateBuilder dateBuilder;
    if (format != DateTimeFormat.HMS && format != DateTimeFormat.SMH) {
        if (timeZone != null) {
            dateBuilder = new DateBuilder(TimeZone.getTimeZone(timeZone));
        } else {
            dateBuilder = new DateBuilder();
        }
        dateBuilder.setDate(year, month, day);
    } else {
        if (timeZone != null) {
            dateBuilder = new DateBuilder(new Date(), TimeZone.getTimeZone(timeZone));
        } else {
            dateBuilder = new DateBuilder(new Date());
        }
    }

    dateBuilder.setTime(hour, minute, second, millisecond);

    return dateBuilder.getDate();
}

public Date nextDateTime(DateTimeFormat format) {
    return nextDateTime(format, null);
}

public Date nextDateTime() {
    return nextDateTime(DateTimeFormat.YMD_HMS, null);

